-- Field notes: read-only reference of WO-derived common problems (from SOP_LIBRARY_DRAFTS.md).
-- Reference only; not runnable SOPs. todo_verify = 1 where a [JOSE: confirm] gap is kept verbatim.
CREATE TABLE IF NOT EXISTS `field_note` (
  `id` TEXT PRIMARY KEY,
  `title` TEXT NOT NULL,
  `applies_to` TEXT NOT NULL,
  `symptoms` TEXT NOT NULL DEFAULT '[]',   -- JSON array of strings
  `checks` TEXT NOT NULL DEFAULT '[]',     -- JSON array of strings, doc order
  `wo_citations` TEXT NOT NULL DEFAULT '[]', -- JSON array of strings
  `todo_verify` INTEGER NOT NULL DEFAULT 0,
  `source_note` TEXT NULL
);

INSERT INTO `field_note` (`id`, `title`, `applies_to`, `symptoms`, `checks`, `wo_citations`, `todo_verify`, `source_note`) VALUES ('fn-condensate-drain-blockage', 'Condensate or drain blockage', 'AC condensate drain: 509 Frontenac unit 204 (ticket 10); 1731/1733 shared drain', '["AC leaking water (ticket 10, 509 Frontenac unit 204)."]', '["Cause: recurring stack blockage at the 1731/1733 shared drain (appliance note). Cause at 509 Frontenac not recorded.", "WO scope: clear condensate drain line (ticket 10). Completion not recorded.", "Check first: [JOSE: confirm] (not in the sources)."]', '["Ticket 10 (no WO#)", "1731/1733 shared drain appliance note (no WO#)"]', 1, 'From SOP_LIBRARY_DRAFTS.md common-problem notes (WO-derived); reference only, not a runnable SOP.');
INSERT INTO `field_note` (`id`, `title`, `applies_to`, `symptoms`, `checks`, `wo_citations`, `todo_verify`, `source_note`) VALUES ('fn-water-heater-tee-eco-scaled-element', 'Water heater tee leak, ECO trips, scaled element', '1721 Bath shared water heater bank (building 2, unit 339)', '["Weeping tee, ECO trips every few days."]', '["Cause (evidenced): scaled lower element (WO-20316).", "WO scope: element, gasket, upper and lower thermostats, tee tightened (WO-20316). Status verified; work not itemized.", "Check first: which heaters in the 1721 bank are in service (3 of 7)."]', '["WO-20316"]', 0, 'From SOP_LIBRARY_DRAFTS.md common-problem notes (WO-derived); reference only, not a runnable SOP.');
INSERT INTO `field_note` (`id`, `title`, `applies_to`, `symptoms`, `checks`, `wo_citations`, `todo_verify`, `source_note`) VALUES ('fn-shorted-element-breaker-trip', 'Shorted element, breaker trip', 'Lower water heater element (1719-273, unit 326)', '["Breaker trips."]', '["Cause (evidenced): lower element shorted to ground (WO-FIELD-900).", "WO record: breaker trip; status done (WO-FIELD-900).", "Check first: breaker, then ground fault on the lower element."]', '["WO-FIELD-900"]', 0, 'From SOP_LIBRARY_DRAFTS.md common-problem notes (WO-derived); reference only, not a runnable SOP.');
INSERT INTO `field_note` (`id`, `title`, `applies_to`, `symptoms`, `checks`, `wo_citations`, `todo_verify`, `source_note`) VALUES ('fn-blower-squeal-vibration', 'Blower squeal or vibration', 'Blower motor (1719-273, unit 326; 137 Amherst Unit 2 zone)', '["High-pitch squeal and vibration."]', '["Cause (evidenced): seized bearings (WO-INTAKE-202).", "WO scope: replace 1/2 HP blower motor and run capacitor (WO-INTAKE-202; ticket 3). Completion not recorded.", "Check first: capacitor rating and motor fit before ordering [JOSE: confirm] (motor fit is not in any source)."]', '["WO-INTAKE-202", "Ticket 3 (child of WO-19970, no WO#)"]', 1, 'From SOP_LIBRARY_DRAFTS.md common-problem notes (WO-derived); reference only, not a runnable SOP.');
INSERT INTO `field_note` (`id`, `title`, `applies_to`, `symptoms`, `checks`, `wo_citations`, `todo_verify`, `source_note`) VALUES ('fn-freezer-noise', 'Freezer noise', 'Freezer, 505 Days Rd unit 103 (505-103)', '["Recurring freezer noise (505-103)."]', '["Cause: [JOSE: confirm]. Not evidenced beyond the complaint.", "WO scope: inspect evaporator fan motor and compressor mounting grommets (WO-19255).", "Check first: evaporator fan motor and compressor mounting grommets."]', '["WO-19255"]', 1, 'From SOP_LIBRARY_DRAFTS.md common-problem notes (WO-derived); reference only, not a runnable SOP.');
INSERT INTO `field_note` (`id`, `title`, `applies_to`, `symptoms`, `checks`, `wo_citations`, `todo_verify`, `source_note`) VALUES ('fn-entry-and-notice', 'Entry and notice', 'Any unit entry that needs 24h notice (1719-273, WO-NOTICE-2026)', '["Work that needs unit entry."]', '["Cause (evidenced): 24h gate on entry (WO-NOTICE-2026; TicketDetailView notice gate; migration 011).", "WO record: notice_needed set (WO-NOTICE-2026); tenant called first (WO-19255).", "Check first: notice sent time and sender; hold status on the ticket."]', '["WO-NOTICE-2026", "WO-19255"]', 0, 'From SOP_LIBRARY_DRAFTS.md common-problem notes (WO-derived); reference only, not a runnable SOP.');
